    public enum PartRoof { Flat, Pyramidal, Cone, Gabled, Hipped, Skillion }

    /// <summary>Un corp al Catedralei (din OpenStreetMap, „building:part”): contur, înălțimi, acoperiș.</summary>
    public struct CathedralPart
    {
        public double[] Outline;   // lat, lon, lat, lon, … (închis sau nu)
        public float MinHeight, Height, RoofHeight;
        public PartRoof Roof;
        /// <summary>Unde stau ferestrele pe zid (m de la sol); 0, 0 = automat.</summary>
        public float WindowFrom, WindowTo;

        public CathedralPart(float minH, float h, PartRoof roof, float roofH, params double[] outline)
        {
            Outline = outline; MinHeight = minH; Height = h; Roof = roof; RoofHeight = roofH;
            WindowFrom = 0f; WindowTo = 0f;
        }
    }

